/**
 * Annotated waveform atlas.
 *
 * Every trace here is generated by the same morphology functions the live simulator uses, so a
 * label that points at "the v wave" points at the sample the engine actually produces. Timings
 * and ranges follow Ragosta & Kennedy, Textbook of Clinical Hemodynamics ch. 2, and Whitener,
 * Konoske & Mark, Best Pract Res Clin Anaesthesiol 2014.
 */

import {
  CARDIAC_PHASE,
  NORMAL_RIGHT_ATRIAL_AMPLITUDES,
  NORMAL_WEDGE_AMPLITUDES,
  PULMONARY_ARTERY_SHAPE,
  SYSTEMIC_ARTERIAL_SHAPE,
  pulsatilePressureShape,
  rightAtrialDeviationMmHg,
  ventricularPressureShape,
  wedgeDeviationMmHg,
  type AtrialWaveAmplitudes,
  type PulsatileShapeOptions,
  type VentricularShapeOptions,
} from '../engine/waveformMorphology'

export type WaveformTraceSpec =
  | {
      readonly kind: 'atrial'
      readonly meanMmHg: number
      readonly amplitudes: AtrialWaveAmplitudes
      readonly landmarks: 'right-atrial' | 'wedge'
    }
  | {
      readonly kind: 'ventricular'
      readonly systolicMmHg: number
      readonly endDiastolicMmHg: number
      readonly shape: VentricularShapeOptions
    }
  | {
      readonly kind: 'pulsatile'
      readonly systolicMmHg: number
      readonly diastolicMmHg: number
      readonly shape: PulsatileShapeOptions
    }
  | {
      /** Over-wedged: a wavering line without distinct a and v waves that drifts upward. */
      readonly kind: 'overwedge'
      readonly baselineMmHg: number
    }
  | {
      /** Incomplete balloon occlusion: a mixture of pulmonary artery and wedge waveforms. */
      readonly kind: 'hybrid'
      readonly wedgeMeanMmHg: number
      readonly paSystolicMmHg: number
      readonly paDiastolicMmHg: number
      readonly contamination: number
    }

/** Pressure in mmHg at a given fraction of the cardiac cycle. */
export function waveformValueAt(spec: WaveformTraceSpec, phase: number): number {
  switch (spec.kind) {
    case 'atrial':
      return (
        spec.meanMmHg +
        (spec.landmarks === 'wedge'
          ? wedgeDeviationMmHg(phase, spec.amplitudes)
          : rightAtrialDeviationMmHg(phase, spec.amplitudes))
      )
    case 'ventricular': {
      const { endDiastolicFraction } = spec.shape
      const nadir =
        (spec.endDiastolicMmHg - spec.systolicMmHg * endDiastolicFraction) /
        (1 - endDiastolicFraction)
      return nadir + (spec.systolicMmHg - nadir) * ventricularPressureShape(phase, spec.shape)
    }
    case 'pulsatile':
      return (
        spec.diastolicMmHg +
        (spec.systolicMmHg - spec.diastolicMmHg) * pulsatilePressureShape(phase, spec.shape)
      )
    case 'overwedge':
      // No identifiable a or v waves — only a low-amplitude waver. Harmonics of the cycle keep
      // the line continuous across beats, because this artifact has no cardiac periodicity.
      return (
        spec.baselineMmHg +
        Math.sin(phase * Math.PI * 2) * 1.1 +
        Math.sin(phase * Math.PI * 6 + 1.1) * 0.55 +
        Math.sin(phase * Math.PI * 16 + 0.4) * 0.2
      )
    case 'hybrid': {
      const wedge = spec.wedgeMeanMmHg + wedgeDeviationMmHg(phase, NORMAL_WEDGE_AMPLITUDES)
      const pulmonaryArtery =
        spec.paDiastolicMmHg +
        (spec.paSystolicMmHg - spec.paDiastolicMmHg) *
          pulsatilePressureShape(phase, PULMONARY_ARTERY_SHAPE)
      return wedge * (1 - spec.contamination) + pulmonaryArtery * spec.contamination
    }
  }
}

export interface WaveformAnnotation {
  readonly id: string
  /** Short symbol drawn on the trace, such as a, c, v, x, or y. */
  readonly label: string
  readonly phase: number
  readonly placement: 'above' | 'below'
  readonly description: string
}

export type WaveformAtlasCategory = 'insertion' | 'abnormal' | 'artifact'

export interface WaveformAtlasEntry {
  readonly id: string
  readonly label: string
  readonly shortLabel: string
  readonly category: WaveformAtlasCategory
  /** Catheter position this trace belongs to, when it is part of the insertion sequence. */
  readonly position: 'ra' | 'rv' | 'pa' | 'wedge' | null
  readonly normalRange: string | null
  readonly insertionDepth: string | null
  readonly scaleMaxMmHg: number
  readonly summary: string
  readonly trace: WaveformTraceSpec
  readonly annotations: readonly WaveformAnnotation[]
  readonly recognitionCues: readonly string[]
  readonly pitfall: string | null
  readonly sourceIds: readonly string[]
}

