export const waveformAtlasById = new Map(waveformAtlasEntries.map((entry) => [entry.id, entry]))

export const insertionSequenceEntries = waveformAtlasEntries.filter(
  (entry) => entry.category === 'insertion',
)

export function waveformAtlasEntriesForPosition(
  position: WaveformAtlasEntry['position'],
): readonly WaveformAtlasEntry[] {
  return waveformAtlasEntries.filter((entry) => entry.position === position)
}

/** Systemic arterial reference trace, used to teach the dicrotic notch and damping artifacts. */
export const arterialReferenceTrace: WaveformTraceSpec = {
  kind: 'pulsatile',
  systolicMmHg: 120,
  diastolicMmHg: 70,
  shape: SYSTEMIC_ARTERIAL_SHAPE,
}
